choose.when:
SELECT b.steel_spec, b.steel_id, steel.`name` NAME, b.material, IFNULL( sum( a.task_quantity ), 0 ) quantity, IFNULL( sum( a.task_quantity * b.net_weight ), 0 ) total_net_weight, IFNULL( sum( a.task_quantity * b.gross_weight ), 0 ) total_gross_weight, IFNULL( sum( a.task_quantity * b.length ), 0 ) total_length FROM mes_building_task a LEFT JOIN tech_machine_part b ON a.product_id = b.id LEFT JOIN sys_steel_classification steel ON steel.id = b.steel_id
a.bool_delete_enum = FALSE AND a.product_type=#{productType}
AND a. monomer_id = #{ monomerId}
AND a.project_id = #{projectId}
AND a.area_id =#{areaId}
AND `name` =#{name}
GROUP BY b.material, b.steel_id, b.steel_spec, steel.`name`

SELECT b.`name`, IFNULL( sum( a.task_quantity ), 0 ) quantity, IFNULL( sum( a.task_quantity * b.net_weight ), 0 ) total_net_weight, IFNULL( sum( a.task_quantity * b.gross_weight ), 0 ) total_gross_weight, IFNULL( sum( a.task_quantity * b.length ), 0 ) total_length , IFNULL( sum( a.task_quantity * b.surface_area ), 0 ) total_area FROM mes_building_task a LEFT JOIN tech_artifact b ON a.product_id = b.id
a.bool_delete_enum = FALSE AND a.product_type=#{productType}
AND a. monomer_id = #{ monomerId}
AND a.project_id = #{projectId}
AND a.area_id =#{areaId}
AND b.`name` =#{name}
GROUP BY b.`name`

SELECT
b.category,
IFNULL( sum( a.task_quantity ), 0 ) quantity,
IFNULL( sum( a.task_quantity * b.length ), 0 ) total_length,
IFNULL( sum( a.task_quantity * b.length * b.width ), 0 ) total_area
FROM
mes_building_task a
LEFT JOIN tech_enclosure b ON a.product_id = b.id

    a.bool_delete_enum = FALSE AND a.product_type=#{productType}
    
        AND a.monomer_id = #{ monomerId}
    
    
        AND a.project_id = #{projectId}
    
    
        AND a.area_id =#{areaId}
    
    
        AND  b.category=#{category}
    

GROUP BY
b.category

mapper.select:
SELECT id, material, serial_number, length, quantity, quantity*length total_length,
width, category, color, thickness, total_area, `name`
specification, net_weight, total_net_weight
, `name`, surface_area area, gross_weight, quantity * surface_area total_area, total_gross_weight
FROM
tech_machine_part
tech_artifact
tech_assemble
tech_enclosure
WHERE bool_delete_enum=false
and project_id = #{projectId}
and monomer_id = #{monomerId}
and area_id=#{areaId}
and material=#{material}
and serial_number like concat('%',#{serialNumber},'%')
and category=#{category}
and name=#{name}
and steel_spec=#{steelSpec} and steel_id=#{steelId}

SELECT a.team_id, a.process_id, process.`name` process_name, user_link.user_name leader_name, team.organization_type, mbf.id 'factory.id', mbf.`name` 'factory.name', mbw.id 'workshop.id', mbw.`name` 'workshop.name', mbpl.id 'productionLine.id', mbpl.`name` 'productionLine.name', a.product_type, a.wage_quota_type, sum(a.price) price, CASE a.product_type WHEN ${@com.hzchum.scim.mes.building.core.api.enums.ProductTypeEnum@MACHINE_PART.getType()} THEN CASE a.wage_quota_type WHEN 1 THEN sum( machine_part.net_weight * a.quantity ) WHEN 2 THEN sum(machine_part.length * a.quantity) ELSE sum(a.quantity) END WHEN ${@com.hzchum.scim.mes.building.core.api.enums.ProductTypeEnum@ARTIFACT.getType()} THEN CASE a.wage_quota_type WHEN 1 THEN sum( artifact.net_weight * a.quantity ) WHEN 2 THEN sum( artifact.length * a.quantity ) WHEN 4 THEN sum( artifact.surface_area * a.quantity ) ELSE sum(a.quantity) END WHEN ${@com.hzchum.scim.mes.building.core.api.enums.ProductTypeEnum@ENCLOSURE.getType()} THEN CASE a.wage_quota_type WHEN 1 THEN sum( enclosure.weight * a.quantity ) WHEN 2 THEN sum( enclosure.length * a.quantity ) WHEN 4 THEN sum( enclosure.length * enclosure.width * a.quantity ) ELSE sum(a.quantity) END ELSE CASE a.wage_quota_type WHEN 1 THEN sum( assemble.net_weight * a.quantity ) WHEN 2 THEN sum( assemble.length * a.quantity ) ELSE sum(a.quantity) END END mate FROM mes_building_produce_team_report_price a LEFT JOIN mes_building_team team ON a.team_id = team.id LEFT JOIN mes_building_team_user_link user_link ON a.team_id = user_link.team_id AND user_link.bool_delete_enum = 0 AND user_link.bool_leader_enum = 1 LEFT JOIN mes_building_process process ON a.process_id = process.id LEFT JOIN mes_building_task task ON task.id=a.task_id LEFT JOIN mes_building_factory mbf ON mbf.id = team.factory_id LEFT JOIN mes_building_workshop mbw ON mbw.id = team.workshop_id LEFT JOIN mes_building_production_line mbpl ON mbpl.id = team.production_line_id LEFT JOIN tech_artifact artifact ON artifact.id=a.product_id LEFT JOIN tech_assemble assemble ON assemble.id=a.product_id LEFT JOIN tech_enclosure enclosure ON enclosure.id=a.product_id LEFT JOIN tech_machine_part machine_part ON machine_part.id=a.product_id
a.product_type & #{productType}
AND team.organization_type=#{organizationType}
AND task.project_id in
#{projectId}
AND task.project_id=#{projectId}
AND task.factory_id=#{factoryId}
AND mbw.name LIKE CONCAT('%', #{workshopName}, '%')
AND mbpl.name LIKE CONCAT('%', #{productionLineName}, '%')
AND process.name LIKE CONCAT('%', #{processName}, '%')
AND DATE(a.create_time)>=DATE(#{startDate})
AND DATE(a.create_time)<=DATE(#{endDate})
GROUP BY a.team_id, a.product_type, a.process_id, process.`name`, user_link.user_name, team.organization_type, mbf.id, mbf.`name`, mbw.id, mbw.`name`, mbpl.id, mbpl.`name`, a.wage_quota_type

SELECT
    IFNULL( sum(a.price),0) price
FROM mes_building_produce_team_report_price a
LEFT JOIN mes_building_task b ON b.id=a.task_id

    
        a.product_type & #{productType}
    
    
        AND b.project_id in
        
            #{projectId}
        
    
    
        AND b.project_id=#{projectId}
    
    
        AND b.factory_id=#{factoryId}
    
    
        AND DATE(a.create_time)>=DATE(#{startDate})
    
    
        AND DATE(a.create_time)<=DATE(#{endDate})
